																						"label": "_HTML",
																						"version": 0,
																						"htmlContent": "<div class=\"buttons-main\">\n\t<span id=\"setButtons\" onclick=\"setButtons(event)\"></span>\n\t<a id=\"approveMerge\" class=\"Button SubmitButton notSelectable Button_Post Resized\" style=\"width: 250px; margin-right: 3px;\">\n\t\t<span class=\"button_span_text text-size-S\"></span>\n\t</a>\n\t<a id=\"cancelMerge\" class=\"Button SubmitButton notSelectable Button_Post Resized\" style=\"width: 250px; margin-left: 3px;\">\n\t\t<span class=\"button_span_text text-size-S\"></span>\n\t</a>\n</div>\n<script>\n\tdocument.querySelector(\"#approveMerge\").addEventListener(\"click\", function ()\n\t{\n\t\twindow.postMessage(\n\t\t{\n\t\t\teventName: \"onClickApprove\",\n\t\t\tcontrol: \"Mergeable_Inquiries_Buttons__\"\n\t\t}, document.location.origin);\n\t});\n\n\tdocument.querySelector(\"#cancelMerge\").addEventListener(\"click\", function ()\n\t{\n\t\twindow.postMessage(\n\t\t{\n\t\t\teventName: \"onClickCancel\",\n\t\t\tcontrol: \"Mergeable_Inquiries_Buttons__\"\n\t\t}, document.location.origin);\n\t});\n\n\tfunction setButtons(evt) {\n\t\tif(evt.approveLabel && evt.cancelLabel) {\n\t\t\tdocument.querySelector(\"#approveMerge > span\").textContent = evt.approveLabel;\n\t\t\tdocument.querySelector(\"#cancelMerge > span\").textContent = evt.cancelLabel;\t\n\t\t}\n\t}\n</script>\n",
																						"css": "@ .buttons-main\n{\n\tmargin-top: 4px;\n\twidth: 100%;\n\tdisplay: flex;\n\tjustify-content: center;\n\tflex-wrap: wrap;\n}",
																						"width": "100%"
																					}
