																			"*": {
																				"NewConversationMessageWarning__": {
																					"type": "HTML",
																					"data": false,
																					"stamp": 348,
																					"options": {
																						"label": "",
																						"htmlContent": "<div class=\"Conversation_Warning_Text\">\n    <span id=\"setMessage\" onclick=\"setMessage(event)\">\n    </span>\n    <a class=\"Button FormButton notSelectable Button_Enabled Resized Conversation_Warning_Button\" type=\"button\">\n        <span>OK</span>\n    </a>\n</div>\n<script>\ndocument.querySelector(\".Conversation_Warning_Button\").addEventListener(\"click\",function(){\n    window.postMessage({eventName: \"onClick\", control: \"NewConversationMessageWarning__\"}, document.location.origin);\n});\n\nfunction setMessage(evt) {\n    if(evt.warningConversationMessage!= null && evt.warningConversationMessage!=\"\") {\n        document.querySelector(\".Conversation_Warning_Text > span\").textContent = evt.warningConversationMessage;\n    }\n}\n</script>\n",
																						"css": "@ .Conversation_Warning_Text\n{\n    background: #F6B221;\n    margin-bottom: 10px;\n    height: 25px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n}@ \n.Conversation_Warning_Button\n{\n    padding-left: 4px;\n    padding-right: 4px;\n    margin: 7px !important;\n    margin-bottom: 7px !important;\n    height: 20px;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n}@ \n.Conversation_Warning_Button > span\n{\n    height: 25px;\n    padding : inherit;\n    font-size: 11px;\n}@ ",
																						"width": "100%",
																						"version": 0
																					}
																				},
																				"ConversationSpacer__": {
																					"type": "Spacer",
																					"data": false,
																					"stamp": 349,
																					"options": {
																						"label": "_ConversationSpacer",
																						"height": "",
																						"width": "",
																						"color": "default",
																						"version": 0
																					}
																				},
																				"GenerateSummary__": {
																					"type": "HTML",
																					"data": false,
																					"stamp": 350,
																					"options": {
																						"label": "",
																						"hidden": true,
																						"version": 0,
																						"htmlContent": "<div class=\"summary-container\">\n\t<span id=\"setSummary\" onclick=\"setSummary(event)\"></span>\n\t<div class=\"button-summary-container\">\n\t\t<a id=\"conversationsSummaryButton\" class=\"Button FormButton notSelectable Light_Button text-right Resized button-summary\" onclick=\"generateSummaryClicked()\">\n\t\t\t<img class=\"synergylogo\" />\n\t\t\t<span id=\"conversationsSummaryButtonLabel\" class=\"button_span_text text-size-S\">%LABEL%</span>\n\t\t\t<span id=\"conversationsSummaryButtonTooltip\" class=\"button-summary-tooltip\">%TOOLTIP%</span>\n\t\t</a>\n\t</div>\n\t<div id=\"conversationsSummary\" class=\"text-summary-container %SUMMARYCLASS%\">\n\t\t<span id=\"conversationsSummaryText\" class=\"text-size-S text-color-default text-summary\">%SUMMARY%</span>\n\t</div>\n</div>\n<script>\n\tfunction generateSummaryClicked ()\n\t{\n\t\twindow.postMessage(\n\t\t{\n\t\t\teventName: \"onClickGenerateSummary\",\n\t\t\tcontrol: \"GenerateSummary__\"\n\t\t}, document.location.origin);\n\t}\n\n\tfunction setSummary (event)\n    {\n\t\tif(event.summary)\n\t\t{\n\t\t\tdocument.querySelector(\"#conversationsSummaryText\").textContent = event.summary;\n\t\t\tdocument.querySelector(\"#conversationsSummary\").classList.remove(\"text-summary-hidden\");\n\t\t\tdocument.querySelector(\"#conversationsSummary\").classList.add(\"text-summary-show\");\n\t\t}\n    }\n</script>\n",
																						"css": ".summary-container {\n\tdisplay: flex;\n\tflex-direction: column;\n}\n\n.button-summary-container, .text-summary-container {\n\twidth: 100%;\n\tbox-sizing: border-box;\n}\n\n.text-summary-container {\n\tdisplay: flex;\n    overflow: auto;\n    padding: 10px;\n\twhite-space: pre-wrap;\n\tword-break: break-word;\n}\n\n.button-summary {\n\tdisplay: inline-flex;\n    align-items: center;\n\tposition: relative;\n\tpadding-left: 10px;\n    padding-right: 10px;\n}\n\n.button-summary img {\n\tpadding-right: 5px;\n}\n\n.button-summary-tooltip {\n\tvisibility: hidden;\n\tbackground-color: #F1AE00;\n\tcolor: #fff;\n\ttext-align: center;\n\tpadding: 5px 5px;\n\tborder-radius: 6px;\n\tposition: absolute;\n\tleft: 105%;\n\tz-index: 1;\n}\n\n.button-summary-tooltip::after {\n\tcontent: \" \";\n\tposition: absolute;\n\ttop: 50%;\n\tright: 100%;\n\tmargin-top: -5px;\n\tborder-width: 5px;\n\tborder-style: solid;\n\tborder-color: transparent #F1AE00 transparent transparent;\n}\n\n.button-summary:hover .button-summary-tooltip {\n\tvisibility: visible;\n}\n\n.text-summary {\n\tpadding: 10px;\n    border: 1.5px dashed #F1AE00;\n    border-radius: 8px;\n}\n\n.text-summary-hidden {\n\tdisplay: none;\n}\n\n.text-summary-show {\n\tdisplay: flex;\n}",
																						"width": "100%"
																					}
																				},
